package com.bank.dataeng.pipeline;

import com.bank.dataeng.model.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// The core ETL engine: extract → transform (clean + dedupe) → load (aggregate).
public class TransactionPipeline {
    private static final Logger log = Logger.getLogger(TransactionPipeline.class.getName());

    // EXTRACT — pull raw records from the source (simulated here).
    public List<RawTransaction> extract() {
        log.info("EXTRACT stage: pulling raw transactions from source");
        return List.of(
            new RawTransaction("TXN-1", "SAV2001", new BigDecimal("1200.00")),
            new RawTransaction("TXN-2", "SAV2001", new BigDecimal("800.00")),
            new RawTransaction("TXN-2", "SAV2001", new BigDecimal("800.00")), // duplicate
            new RawTransaction("TXN-3", "CUR3001", new BigDecimal("5000.00")),
            new RawTransaction("TXN-4", "CUR3001", null),                     // invalid
            new RawTransaction("TXN-5", "CUR3001", new BigDecimal("-50.00"))  // invalid sign
        );
    }

    // TRANSFORM — drop invalid rows, deduplicate by txn id.
    public List<CleanTransaction> transform(List<RawTransaction> raw) {
        log.info("TRANSFORM stage: cleaning and deduplicating");
        Set<String> seen = new HashSet<>();
        List<CleanTransaction> clean = new ArrayList<>();
        for (RawTransaction r : raw) {
            if (r.getAmount() == null || r.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
                log.warning(() -> "Dropping invalid record " + r.getTxnId());
                continue;
            }
            if (!seen.add(r.getTxnId())) {
                log.warning(() -> "Dropping duplicate record " + r.getTxnId());
                continue;
            }
            clean.add(new CleanTransaction(r.getTxnId(), r.getAccountId(), r.getAmount()));
        }
        return clean;
    }

    // LOAD — aggregate per account and hand off to the warehouse.
    public Map<String, AccountSummary> load(List<CleanTransaction> clean) {
        log.info("LOAD stage: aggregating per account for the warehouse");
        Map<String, AccountSummary> byAccount = new LinkedHashMap<>();
        for (CleanTransaction c : clean) {
            byAccount.computeIfAbsent(c.getAccountId(), AccountSummary::new).add(c.getAmount());
        }
        return byAccount;
    }
}
