package com.bank.dataeng;

import com.bank.dataeng.model.*;
import com.bank.dataeng.pipeline.TransactionPipeline;
import java.util.*;
import java.util.logging.Logger;

public class DataEngApplication {
    private static final Logger log = Logger.getLogger(DataEngApplication.class.getName());

    public static void main(String[] args) {
        TransactionPipeline pipeline = new TransactionPipeline();
        List<RawTransaction> raw = pipeline.extract();
        List<CleanTransaction> clean = pipeline.transform(raw);
        Map<String, AccountSummary> summary = pipeline.load(clean);

        log.info("=== WAREHOUSE-READY SUMMARY ===");
        summary.values().forEach(s ->
            log.info(s.getAccountId() + " total=" + s.getTotal() + " count=" + s.getCount()));
    }
}
